<script setup>
import {onMounted,ref} from 'vue';import {get,fmt,pct} from '../api/client';import MetricCard from '../components/MetricCard.vue';import DataTable from '../components/DataTable.vue'
const data=ref(null),error=ref('');onMounted(async()=>{try{data.value=await get('/dashboard')}catch(e){error.value=e.message}})
const cols=[{label:'分组',key:'top_n',format:v=>`Top${v}`},{label:'上涨比例',key:'up_rate',format:pct},{label:'平均收益',key:'avg_return',format:pct,class:v=>v>0?'positive':'negative'},{label:'市场收益',key:'market_avg_return',format:pct},{label:'超额收益',key:'excess_return',format:pct,class:v=>v>0?'positive':'negative'}]
</script><template><div v-if="error" class="empty">{{error}}</div><div v-else-if="!data" class="empty">加载中…</div><template v-else><div class="grid"><MetricCard label="股票数量" :value="fmt(data.stats.stock_count,0)" sub="SH · SZ · BJ"/><MetricCard label="日线记录" :value="fmt(data.stats.daily_count,0)" :sub="`${data.stats.first_date} — ${data.stats.latest_date}`"/><MetricCard label="预测批次" :value="data.stats.prediction_runs" :sub="`最新 ${data.latest_prediction.base_date||'—'}`"/><MetricCard label="正式验证" :value="data.stats.verification_runs" sub="收盘后自动生成"/></div><div class="section"><h2>最新模型样本表现</h2><div class="grid"><MetricCard label="样本上涨率" :value="pct(data.latest_prediction.backtest_up_rate)"/><MetricCard label="候选平均" :value="pct(data.latest_prediction.backtest_avg_return)"/><MetricCard label="市场平均" :value="pct(data.latest_prediction.market_avg_return)"/><MetricCard label="样本超额" :value="pct(data.latest_prediction.excess_return)"/></div></div><div class="section"><h2>最新盘中 TopN</h2><DataTable :columns="cols" :rows="data.latest_intraday_groups"/></div></template></template>
